<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Shared\Security;

/**
 * Port to keep at rest secrets that must be recovered in plain text (TOTP seeds, SMTP passwords...).
 *
 * The sealed value is self-describing: "sealed:<key-id>:<payload>", so the implementation can
 * choose the key (or the backend: local key ring, Vault transit, KMS...) needed to open it and
 * detect values sealed with old keys.
 *
 * The context is bound to the sealed value (as AAD or derivation context): a value sealed for a
 * context can not be opened with another one, so copying it to another field or row is useless.
 */
interface ReversibleSecretStorage
{
    /**
     * Prefix of every value sealed by these port.
     */
    public const string SEALED_PREFIX = 'sealed:';

    /**
     * Seals the plain value for the given context with the current key.
     */
    public function seal(string $plain, string $context): string;

    /**
     * Opens a sealed value.
     *
     * @throws \InvalidArgumentException if the value is malformed, the key is unknown or the context does not match.
     */
    public function open(string $sealed, string $context): string;

    /**
     * True if the value was sealed with a key that is not the current one.
     *
     * @throws \InvalidArgumentException if the value is not a sealed one.
     */
    public function needsReseal(string $sealed): bool;
}
